import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] secondLine = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(secondLine[i]);
        }

        int n1 = n / 2;
        List<Integer> a1 = new ArrayList<>();
        List<Integer> a2 = new ArrayList<>();

        generateSums1(0, 0, a, n1, m, a1);
        generateSums2(n1, 0, a, n, m, a2);

        int maxSum = 0;
        Set<Integer> setA1 = new HashSet<>(a1);
        List<Integer> uniqueA1 = new ArrayList<>(setA1);
        Collections.sort(uniqueA1);

        for (int val : a2) {
            int j = lowerBound(uniqueA1, m - val);
            if (j > 0) {
                int candidate = uniqueA1.get(j - 1) + val;
                if (candidate > maxSum) {
                    maxSum = candidate;
                }
            }
        }
        System.out.println(maxSum);
    }

    private static void generateSums1(int i, int total, int[] a, int n1, int m, List<Integer> a1) {
        if (i == n1) {
            a1.add(total % m);
        } else {
            generateSums1(i + 1, total + a[i], a, n1, m, a1);
            generateSums1(i + 1, total, a, n1, m, a1);
        }
    }

    private static void generateSums2(int i, int total, int[] a, int n, int m, List<Integer> a2) {
        if (i == n) {
            a2.add(total % m);
        } else {
            generateSums2(i + 1, total + a[i], a, n, m, a2);
            generateSums2(i + 1, total, a, n, m, a2);
        }
    }

    private static int lowerBound(List<Integer> list, int key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) < key) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}
